import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { canonicalJson, sha256Hex } from '../../src/lib/hash';
import { MockPlanRepository } from '../../src/modules/campaignPlans/mockRepository';
import { createCampaignPlanRoutes } from '../../src/modules/campaignPlans/routes';
import { submitCampaignPlan, type StoredArtifact } from '../../src/modules/campaignPlans/service';
import type { CampaignPlan } from '../../src/modules/campaignPlans/schemas';

// Generated by the Python HTTP smoke: catches Python -> TypeScript contract drift.
const fixture = JSON.parse(readFileSync(resolve(process.cwd(), '../../qa/evidence/qq04/mock-report.json'), 'utf8'));
function setup() {
  const repo = new MockPlanRepository();
  const plan = structuredClone(fixture.plan.result) as CampaignPlan;
  const artifact: StoredArtifact = { ref: structuredClone(fixture.plan.artifact), result: plan,
    evidence: structuredClone(fixture.plan.evidence) };
  const context = { snapshot_id: plan.context_snapshot_id, profile_version: 1,
    approved_sources: structuredClone(fixture.research_request.approved_source_versions) };
  repo.seedContext(plan.workspace_id, context);
  repo.seedArtifact({ ref: fixture.research.artifact, result: fixture.research.result, evidence: fixture.research.evidence });
  function save() {
    artifact.ref.content_hash = sha256Hex(canonicalJson({ result: artifact.result, evidence: artifact.evidence }));
    repo.seedArtifact(artifact);
  }
  save();
  return { repo, plan, artifact, context, save, deps: { repo, allowSynthetic: true } };
}

describe('QQ-04 backend plan boundary', () => {
  it('accepts the Python plan, enqueues only the root and deduplicates concurrent retries', async () => {
    const s = setup();
    const routes = createCampaignPlanRoutes(s.deps);
    const results = await Promise.all([routes.handleSubmit(s.plan.workspace_id, s.artifact.ref),
      routes.handleSubmit(s.plan.workspace_id, s.artifact.ref)]);
    expect(results.map(r => r.status).sort()).toEqual([200, 201]);
    expect(s.repo.records).toHaveLength(1);
    const record = s.repo.records[0];
    expect(record.outbox).toEqual([{ task_id: s.plan.tasks[0].task_id, operation: 'seo.local_draft' }]);
    expect(record.task_states[s.plan.tasks[1].task_id]).toBe('blocked');
  });

  it.each(['role', 'tool', 'cycle', 'unknown_dependency', 'duplicate_id', 'handoff', 'approval',
    'topic', 'missing_cta', 'blocked', 'snapshot', 'profile', 'version', 'foreign_ref', 'fake_selection'])
  ('rejects %s before writing any campaign/task/outbox', async change => {
    const s = setup();
    const seo = s.plan.tasks[0];
    if (change === 'role') (seo as unknown as { role: string }).role = 'admin';
    if (change === 'tool') (seo.tools as string[]).push('publish');
    if (change === 'cycle') seo.depends_on = [s.plan.tasks[1].task_id];
    if (change === 'unknown_dependency') s.plan.tasks[1].depends_on = [s.plan.plan_id];
    if (change === 'duplicate_id') s.plan.tasks[1].task_id = seo.task_id;
    if (change === 'handoff') s.plan.tasks[1].dependency_artifact_from = [];
    if (change === 'approval') (seo as unknown as { requires_human_approval: boolean }).requires_human_approval = false;
    if (change === 'topic') seo.brief.topic = 'Unrelated topic';
    if (change === 'missing_cta') seo.brief.cta = null;
    if (change === 'blocked') s.plan.missing_facts.push('confirmed_offer');
    if (change === 'snapshot') s.plan.context_snapshot_id = s.plan.plan_id;
    if (change === 'profile') s.plan.profile_version = 2;
    if (change === 'version') s.plan.input_version = 2;
    if (change === 'foreign_ref') s.plan.research_artifact.workspace_id = s.plan.plan_id;
    if (change === 'fake_selection') s.plan.selected_opportunity!.topic = 'Forged research';
    s.save();
    const response = await createCampaignPlanRoutes(s.deps).handleSubmit(s.plan.workspace_id, s.artifact.ref);
    expect(response.status).toBe(422);
    expect(s.repo.records).toEqual([]);
  });

  it('enqueues a plan whose research only carries coverage notes', async () => {
    const s = setup();
    const research = structuredClone(fixture.research);
    research.result.missing_facts = ['complete_research_explanation', 'source_gap:housing'];
    research.artifact.content_hash = sha256Hex(canonicalJson({ result: research.result, evidence: research.evidence }));
    s.repo.seedArtifact({ ref: research.artifact, result: research.result, evidence: research.evidence });
    s.plan.research_artifact = research.artifact;
    for (const task of s.plan.tasks) task.input_artifact_refs = [research.artifact];
    s.plan.missing_facts.push('complete_research_explanation', 'source_gap:housing');
    s.save();
    const response = await createCampaignPlanRoutes(s.deps).handleSubmit(s.plan.workspace_id, s.artifact.ref);
    expect(response.status).toBe(201);
    expect(s.repo.records).toHaveLength(1);
  });

  it('rejects modified content, wrong tenant and stale artifact refs', async () => {
    const s = setup();
    s.plan.objective = 'Changed after hash';
    s.repo.seedArtifact(s.artifact);
    await expect(submitCampaignPlan(s.deps, s.plan.workspace_id, s.artifact.ref)).rejects.toMatchObject({ code: 'ARTIFACT_HASH_MISMATCH' });
    await expect(submitCampaignPlan(s.deps, s.plan.plan_id, s.artifact.ref)).rejects.toMatchObject({ code: 'TENANT_SCOPE_VIOLATION' });
    s.save();
    await expect(submitCampaignPlan(s.deps, s.plan.workspace_id, { ...s.artifact.ref, version: 99 })).rejects.toMatchObject({ code: 'ARTIFACT_MISMATCH' });
    expect(s.repo.records).toEqual([]);
  });

  it('rejects revoked research and disallows mock plans by default', async () => {
    const s = setup();
    await expect(submitCampaignPlan({ repo: s.repo }, s.plan.workspace_id, s.artifact.ref)).rejects.toMatchObject({ code: 'SYNTHETIC_NOT_ALLOWED' });
    s.repo.seedContext(s.plan.workspace_id, { ...s.context, approved_sources: [] });
    await expect(submitCampaignPlan(s.deps, s.plan.workspace_id, s.artifact.ref)).rejects.toMatchObject({ code: 'SOURCE_NOT_APPROVED' });
    expect(s.repo.records).toEqual([]);
  });

  it('commit failure writes nothing and retry can recover', async () => {
    const s = setup();
    s.repo.failNextCommit = true;
    const routes = createCampaignPlanRoutes(s.deps);
    expect((await routes.handleSubmit(s.plan.workspace_id, s.artifact.ref)).status).toBe(500);
    expect(s.repo.records).toEqual([]);
    expect((await routes.handleSubmit(s.plan.workspace_id, s.artifact.ref)).status).toBe(201);
  });

  it('context changes during validation fail at commit', async () => {
    const s = setup();
    const accept = s.repo.accept.bind(s.repo);
    s.repo.accept = async (plan, context) => {
      s.repo.seedContext(plan.workspace_id, { ...context, profile_version: 2 });
      return accept(plan, context);
    };
    await expect(submitCampaignPlan(s.deps, s.plan.workspace_id, s.artifact.ref)).rejects.toMatchObject({ code: 'STALE_CONTEXT' });
    expect(s.repo.records).toEqual([]);
  });

  it('same plan ID/version with new content conflicts', async () => {
    const s = setup();
    await submitCampaignPlan(s.deps, s.plan.workspace_id, s.artifact.ref);
    s.plan.objective = 'New objective';
    s.save();
    await expect(submitCampaignPlan(s.deps, s.plan.workspace_id, s.artifact.ref)).rejects.toMatchObject({ code: 'PLAN_CONFLICT', status: 409 });
    expect(s.repo.records).toHaveLength(1);
  });
});
